<?php
declare(strict_types=1);ini_set('session.use_strict_mode','1');session_set_cookie_params(['httponly'=>true,'secure'=>true,'samesite'=>'Strict','path'=>'/']);session_start();header('Content-Type: application/json; charset=UTF-8');header('Cache-Control: no-store');if(($_SESSION['admin_authenticated']??false)!==true){http_response_code(401);echo json_encode(['error'=>'Yetkisiz']);exit;}const CONFIG_FILE='/var/www/vhosts/mamonestate.com/mamonestate-config.env';
function cfg(): array {$out=[];if(is_readable(CONFIG_FILE)){foreach(file(CONFIG_FILE,FILE_IGNORE_NEW_LINES)?:[] as $line){if(!str_contains($line,'=')||str_starts_with(trim($line),'#'))continue;[$k,$v]=explode('=',$line,2);$out[trim($k)]=trim($v," \t\n\r\0\x0B\"'");}}return $out;}function database(array $c): PDO {$x=parse_url($c['DATABASE_URL']??'');if(!$x)throw new RuntimeException('Veritabanı ayarı eksik');return new PDO(sprintf('pgsql:host=%s;port=%d;dbname=%s',$x['host'],$x['port']??5432,ltrim($x['path'],'/')),urldecode($x['user']??''),urldecode($x['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}function read_setting(PDO $p,string $k,array $f): array {$s=$p->prepare('select value::text from site_settings where key=?');$s->execute([$k]);$v=$s->fetchColumn();return $v?array_merge($f,json_decode($v,true)?:[]):$f;}function save_setting(PDO $p,string $k,array $v): void {$s=$p->prepare('insert into site_settings(key,value) values(?,?::jsonb) on conflict(key) do update set value=excluded.value,updated_at=now()');$s->execute([$k,json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}function update_config(array $changes): void {$lines=file(CONFIG_FILE,FILE_IGNORE_NEW_LINES)?:[];$done=[];foreach($lines as &$line){if(!str_contains($line,'=')||str_starts_with(trim($line),'#'))continue;[$key]=explode('=',$line,2);$key=trim($key);if(array_key_exists($key,$changes)){$line=$key.'='.$changes[$key];$done[$key]=true;}}unset($line);foreach($changes as $key=>$value)if(!isset($done[$key]))$lines[]=$key.'='.$value;$tmp=CONFIG_FILE.'.tmp';if(file_put_contents($tmp,implode(PHP_EOL,$lines).PHP_EOL,LOCK_EX)===false||!rename($tmp,CONFIG_FILE))throw new RuntimeException('Yapılandırma yazılamadı');chmod(CONFIG_FILE,0600);}
try{$c=cfg();$p=database($c);$site=['siteName'=>'Mamon Estate','phone'=>'0533 057 79 13','email'=>'info@mamonestate.com','whatsapp'=>'0533 057 79 13','address'=>'Antalya, Türkiye','defaultLanguage'=>'tr','defaultCurrency'=>'TRY'];$seo=['title'=>'Akdeniz & Ege Satılık Villa ve Daire | Mamon Estate','description'=>'Akdeniz ve Ege seçkin gayrimenkul portföyü.','keywords'=>'akdeniz emlak, ege villa','canonical'=>'https://mamonestate.com/','socialImage'=>'','indexing'=>'1','sitemap'=>'1'];if($_SERVER['REQUEST_METHOD']==='GET'){echo json_encode(['site'=>read_setting($p,'site',$site),'seo'=>read_setting($p,'seo',$seo),'deepseek'=>array_merge(read_setting($p,'deepseek',['temperature'=>'0.7','systemPrompt'=>'Mamon Estate çok dilli gayrimenkul danışmanısın.']),['model'=>$c['DEEPSEEK_MODEL']??'deepseek-chat','apiKeyConfigured'=>!empty($c['DEEPSEEK_API_KEY'])])],JSON_UNESCAPED_UNICODE);exit;}$type=(string)($_POST['type']??'');$data=$_POST;unset($data['type']);if($type==='site')save_setting($p,'site',$data);elseif($type==='seo'){if(!isset($data['indexing']))$data['indexing']='0';if(!isset($data['sitemap']))$data['sitemap']='0';save_setting($p,'seo',$data);}elseif($type==='deepseek'){$key=trim((string)($data['apiKey']??''));$model=in_array($data['model']??'',['deepseek-chat','deepseek-reasoner'],true)?$data['model']:'deepseek-chat';$changes=['DEEPSEEK_MODEL'=>$model];if($key!=='')$changes['DEEPSEEK_API_KEY']=str_replace(["\r","\n"],'',$key);update_config($changes);unset($data['apiKey'],$data['model']);save_setting($p,'deepseek',$data);}else throw new RuntimeException('Geçersiz grup');echo json_encode(['ok'=>true]);}catch(Throwable $e){error_log('Admin settings: '.$e->getMessage());http_response_code(500);echo json_encode(['error'=>'Ayarlar kaydedilemedi.']);}
